assert isinstance(j["recolhimento_devido"], (int,float))
assert isinstance(j["condicao_dispensa"], str)
print("schema OK")

# 2) ground truth from XMLs
def xval(path, tag):
    t = open(path, encoding="utf-8").read()
    m = re.search(rf"<{tag}>([^<]*)</{tag}>", t)
    return m.group(1) if m else None

truth_s, truth_e = {}, {}
for p in sorted(glob.glob(f"{D}/documents/saidas/*.xml")):
    n = int(xval(p,"nNF")); 
    truth_s[n] = dict(
        valor=float(xval(p,"vNF")),
        dhEmi=xval(p,"dhEmi"), cStat=xval(p,"cStat"),
        has_grp = "<IBSCBS>" in open(p,encoding='utf-8').read(),
        vCBS=float(xval(p,"vCBS") or 0), vIBSUF=float(xval(p,"vIBSUF") or 0), vIBSMun=float(xval(p,"vIBSMun") or 0),
        pCBS=xval(p,"pCBS"), pIBSUF=xval(p,"pIBSUF"),
