    n = int(xval(p,"nNF"))
    t = open(p,encoding='utf-8').read()
    truth_e[n] = dict(valor=float(xval(p,"vNF")), has_grp="<IBSCBS>" in t,
        vCBS=float(xval(p,"vCBS") or 0), vIBSUF=float(xval(p,"vIBSUF") or 0), vIBSMun=float(xval(p,"vIBSMun") or 0),
