for s in j["saidas"]:
    g = truth_s[s["numero"]]
    if abs(g["valor"] - s["valor"]) > 1e-6: errs.append(("valor", s["numero"], g["valor"], s["valor"]))
    d = g["dhEmi"][:10].replace("-","/")[::-1][:8]  # dd/mm
    d_iso = g["dhEmi"][:10]
    post = d_iso >= "2026-08-03"
    if post:
        if not g["has_grp"]:
            exp = "irregular"
        elif abs(g["vCBS"] - round(g["valor"]*0.009,2)) > 0.01 or abs(g["vIBSUF"]+g["vIBSMun"] - round(g["valor"]*0.001,2)) > 0.01:
            exp = "irregular"
        else: exp = "regular"
    else:
        exp = "regular"
    if s["situacao"] != exp: errs.append(("situacao", s["numero"], exp, s["situacao"]))
    # debits computed at correct rates
    if abs(s["cbs"] - round(g["valor"]*0.009,2)) > 0.011: errs.append(("cbs", s["numero"], round(g["valor"]*0.009,2), s["cbs"]))
    if abs(s["ibs"] - round(g["valor"]*0.001,2)) > 0.011: errs.append(("ibs", s["numero"], round(g["valor"]*0.001,2), s["ibs"]))
    if s["data"] != d_iso: errs.append(("data", s["numero"], d_iso, s["data"]))

# entradas
for e in j["entradas"]:
    g = truth_e[e["numero"]]
    if abs(g["valor"] - e["valor"]) > 1e-6: errs.append(("evalor", e["numero"]))
    creditavel = g["has_grp"] and g["CRT"]=="3"
    exp_cbs = round(g["vCBS"],2) if creditavel else 0.0
    exp_ibs = round(g["vIBSUF"]+g["vIBSMun"],2) if creditavel else 0.0
    if abs(e["credito_cbs"]-exp_cbs)>0.011 or abs(e["credito_ibs"]-exp_ibs)>0.011:
        errs.append(("cred", e["numero"], (exp_cbs,exp_ibs),(e["credito_cbs"],e["credito_ibs"])))

# totais
t = j["totais"]
def rnd(x): return round(x+1e-9,2)
checks = {
 "debito_cbs": rnd(sum(s["cbs"] for s in j["saidas"])),
 "debito_ibs": rnd(sum(s["ibs"] for s in j["saidas"])),
 "credito_cbs": rnd(sum(e["credito_cbs"] for e in j["entradas"])),
 "credito_ibs": rnd(sum(e["credito_ibs"] for e in j["entradas"])),
}
checks["saldo_cbs"] = rnd(checks["debito_cbs"]-checks["credito_cbs"])
checks["saldo_ibs"] = rnd(checks["debito_ibs"]-checks["credito_ibs"])
for k,v in checks.items():
    if abs(t[k]-v)>0.011: errs.append(("total",k,v,t[k]))

print("GRAND TOTAL check:", t)
print("saidas count:", len(j["saidas"]), "entradas:", len(j["entradas"]))
print("ERRORS:", errs if errs else "none")
print("recolhimento_devido:", j["recolhimento_devido"])
print("condicao_dispensa[:120]:", j["condicao_dispensa"][:120])

